from dental_release.paths import expand as _release_expand
from common import *
from screening import partition
import csv, sys, time

def fmt(v):
    return 'UNKNOWN' if v is None else f'{v:.3f}'

def interval(p, ci):
    return fmt(p) + ' [' + ', '.join((fmt(v) for v in ci)) + ']' if ci else 'UNKNOWN'

def main():
    st = time.perf_counter()
    rounds = {r: read(P / f'raw/RESULTS_{r}.json') for r in ['R1', 'R2', 'R3', 'R4']}
    pr = read(P / 'PREREG_R4.json')
    frozen = {r: read(P / ('FROZEN_PREDICTIONS.json' if r == 'R1' else f'FROZEN_PREDICTIONS_{r}.json')) for r in rounds}
    names = dict(zip(FINDINGS, NAMES))
    names['open_bite'] = 'Open bite , optional reported region'
    rows = []
    table = ['| Fynd | Test +/− | Sensitivity Sp ≥ 0,90 [bootstrap 95% ] | Sensitivity Sp ≥ 0,95 [bootstrap 95% ] | Bortfall | Brusgolv |', '|---|---:|---|---|---:|---|']
    deploy = ['| Fynd | Sp-goal | Sensitivity [Wilson 95%] | Faktisk Sp [Wilson 95%] | Frozen gate |', '|---|---:|---|---|---|']
    noise = ['| Fynd | Dubbla test cases +/− | Total rapportkonflikt | Positive compliance [Wilson 95% ] | Negative compliance |', '|---|---:|---:|---|---:|']
