        if f == 'open_bite':
            rr = rounds['R4']
            methods = rr['methods']
            dropped = rr['test_rejected']
            n = rr['test_n']
            rd = 'R4'
            label = 'any_open_bite'
        else:
            rr = rounds['R2']['findings'][f]
            methods = rr['methods']
            dropped = rr['test_rejected']
            n = rr['test_scored']
            rd = 'R2'
