    cost = dict(new_geometry_preparation='NONE; reused archived geometry', label_extraction=read(P / 'raw/LABEL_COST.json'), prediction_and_fit={r: {k: v for (k, v) in fr.items() if k in ['wall_s', 'peak_rss_MiB', 'fit_cost', 'train_n', 'train_pos', 'feature_count']} for (r, fr) in frozen.items()}, evaluation_wall_s={r: x['evaluation_wall_s'] for (r, x) in rounds.items()}, query=read(P / 'raw/DEMO_CASE.json'), figure=read(P / 'raw/FIGURE_COST.json'), inherited_X7_geometry_wall_s=x7['preparation_seconds'], inherited_X7_fits_and_discovery=x7, inherited_X21_geometry_and_all_recorded_round_costs=x21, failed_R2_progress_print_fit_seconds=None, failed_R2_cost_status='One first-finding fit repeated; its wall time not separately instrumented. Retained failure source/log. UNKNOWN, not zero.', external_measurement='NOT_RUN', independent_rater_review='NOT_RUN', token_and_source_search_cost='UNKNOWN', full_cost_closed=False, no_speedup_claim=True)
